+            new NetworkService(Collections.emptyList()),
+            threadPool,
+            xContentRegistry(),
+            dispatcher,
+            randomClusterSettings(),
+            new SharedGroupFactory(settings),
+            Tracer.NOOP,
+            new TLSConfig(sslService.getHttpTransportSSLConfiguration(), sslService::createSSLEngine),
+            null,
